from taf.rfrl.csv4all.resources.test_cases import SiteResetTest


class PowerSiteResetTest(SiteResetTest):

    def test_operation(self, node):
        if self.report_to_rp:
            self.test_reporter.get_start_time()
        self.add_all_allowed_specific_faults(node)
        node.power_reset_site(graceful_cell_shutdown=self.graceful_cell_shutdown)
